const $=s=>document.querySelector(s);
let state={favorites:[],done:[],notes:{}};
let storageAvailable=true;
try{const saved=JSON.parse(localStorage.getItem('beacon-business-v1'));if(saved&&typeof saved==='object')state={favorites:Array.isArray(saved.favorites)?saved.favorites.filter(id=>tips.some(t=>t.id===id)):[],done:Array.isArray(saved.done)?saved.done.filter(id=>tips.some(t=>t.id===id)):[],notes:saved.notes&&typeof saved.notes==='object'?saved.notes:{}}}catch{storageAvailable=false}
let view='all',category=-1,selected=1,query='',sort='default';
const palette=[['#edf3ef','#517a63'],['#edf1f9','#6a7fa4'],['#fbf1e7','#aa885e'],['#eef5f3','#5a8579'],['#f4eef7','#927aa2'],['#eef1f5','#6a7f96'],['#f7f0ec','#a67d65'],['#f7f3e5','#99874e'],['#eaf4f5','#518992'],['#edf4e9','#788c5c']];
function persist(){try{localStorage.setItem('beacon-business-v1',JSON.stringify(state))}catch{storageAvailable=false;toast('No se pueden guardar los cambios. Exporta tu espacio para conservarlo.')}updateStats()}
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3300)}
function updateStats(){let n=state.done.length;$('#fav-count').textContent=state.favorites.length;$('#done-count').textContent=n;$('#stat-done').innerHTML=n+' <em>/ 100</em>';$('#percent').textContent=n+'%';$('#ring').style.setProperty('--p',n)}
function toggle(type,id){state[type]=state[type].includes(id)?state[type].filter(x=>x!==id):[...state[type],id];persist();render();if($('#detail').open)updateDetailButtons()}
function normalize(s){return s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()}
function render(){
 const titles={all:['Tu biblioteca de ideas','Encuentra el consejo que necesitas para tu próximo paso.'],favorites:['Tus ideas favoritas','Guarda los consejos que quieres tener siempre a mano.'],plan:['Mi progreso','Revisa tus notas y las acciones que ya has completado.']};
 $('#section-title').textContent=titles[view][0];$('#section-subtitle').textContent=titles[view][1];
 document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view&&category===-1);b.setAttribute('aria-pressed',String(b.dataset.view===view&&category===-1))});
 document.querySelectorAll('[data-cat]').forEach(b=>{b.classList.toggle('active',Number(b.dataset.cat)===category);b.setAttribute('aria-pressed',String(Number(b.dataset.cat)===category))});
 let list=tips.filter(t=>(category===-1||t.category===category)&&(view!=='favorites'||state.favorites.includes(t.id))&&(view!=='plan'||state.done.includes(t.id)||!!state.notes[t.id])&&normalize(t.title+' '+t.body+' '+t.action+' '+categories[t.category][0]).includes(normalize(query)));
 if(sort==='az')list.sort((a,b)=>a.title.localeCompare(b.title,'es'));if(sort==='pending')list.sort((a,b)=>Number(state.done.includes(a.id))-Number(state.done.includes(b.id)));
 $('#result-count').textContent=list.length+' consejo'+(list.length===1?'':'s');$('#cards').replaceChildren();$('#empty').hidden=list.length>0;
 $('#empty-text').textContent=query||category!==-1?'Prueba con otra palabra o cambia el tema.':view==='favorites'?'Pulsa el corazón de un consejo para guardarlo aquí.':view==='plan'?'Abre un consejo y añade una nota o marca su acción como completada.':'Prueba otra búsqueda.';
 for(const t of list){const done=state.done.includes(t.id),fav=state.favorites.includes(t.id);const card=document.createElement('article');card.className='card';card.style.setProperty('--tag-bg',palette[t.category][0]);card.style.setProperty('--tag-color',palette[t.category][1]);card.innerHTML=`<div class="card-top"><span class="tag">${categories[t.category][1]} &nbsp;${categories[t.category][0]}</span><button class="icon-button ${fav?'saved':''}" aria-label="${fav?'Quitar de':'Guardar en'} favoritos: ${t.title}" aria-pressed="${fav}">${fav?'♥':'♡'}</button></div><div class="card-index">CONSEJO ${String(t.id).padStart(3,'0')}</div><h3>${t.title}</h3><p>${t.body}</p><div class="card-bottom"><button class="read-button" aria-label="Leer consejo: ${t.title}">Explorar consejo ＋</button><span class="card-status ${done?'done':''}">${done?'✓ Completado':state.notes[t.id]?'✎ Con notas':'2 min de claridad'}</span></div>`;card.querySelector('.icon-button').onclick=()=>toggle('favorites',t.id);card.querySelector('.read-button').onclick=()=>openTip(t.id);$('#cards').append(card)}
}
function updateDetailButtons(){const fav=state.favorites.includes(selected),done=state.done.includes(selected);$('#detail-fav').textContent=fav?'♥ Guardado en favoritos':'♡ Guardar favorito';$('#detail-fav').setAttribute('aria-pressed',String(fav));$('#detail-done').textContent=done?'✓ Completado · Desmarcar':'Marcar como completado';$('#detail-done').setAttribute('aria-pressed',String(done))}
function openTip(id){selected=id;const t=tips[id-1];$('#detail-category').textContent=categories[t.category][1]+' '+categories[t.category][0];$('#detail-number').textContent='CONSEJO '+String(id).padStart(3,'0');$('#detail-title').textContent=t.title;$('#detail-body').textContent=t.body;$('#detail-action').textContent=t.action;$('#note').value=typeof state.notes[id]==='string'?state.notes[id]:'';$('#detail-position').textContent=id+' / 100';$('#prev').disabled=id===1;$('#next').disabled=id===100;updateDetailButtons();if(!$('#detail').open){$('#detail').showModal();document.body.style.overflow='hidden'}$('#detail').scrollTop=0}
function setCategory(c){category=c;render()}
function init(){
 const all=document.createElement('button');all.className='chip active';all.dataset.cat='-1';all.textContent='Todos los temas';all.onclick=()=>setCategory(-1);$('#chips').append(all);
 categories.forEach(([name,symbol],i)=>{let chip=document.createElement('button');chip.className='chip';chip.dataset.cat=i;chip.textContent=name;chip.onclick=()=>setCategory(i);$('#chips').append(chip);let side=document.createElement('button');side.className='nav category-nav';side.dataset.cat=i;side.innerHTML=`<span>${symbol}</span>${name}`;side.onclick=()=>{view='all';setCategory(i);$('.library').scrollIntoView({behavior:'smooth',block:'start'})};$('#side-categories').append(side)});
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;category=-1;query='';$('#search').value='';render();$('.library').scrollIntoView({behavior:'smooth',block:'start'})});
 $('#search').oninput=e=>{query=e.target.value;render()};$('#sort').onchange=e=>{sort=e.target.value;render()};$('#reset').onclick=()=>{view='all';category=-1;query='';$('#search').value='';render()};
 const date=new Date();const day=Math.floor((Date.UTC(date.getFullYear(),date.getMonth(),date.getDate())-Date.UTC(date.getFullYear(),0,1))/86400000);const daily=tips[day%100];$('#daily-category').textContent=categories[daily.category][0]+' · Consejo '+String(daily.id).padStart(3,'0');$('#daily-title').textContent=daily.title;$('#daily-body').textContent=daily.body;$('#daily-open').onclick=()=>openTip(daily.id);$('.edition b').textContent=String(daily.id).padStart(2,'0')+' / 100';$('#year').textContent=date.getFullYear();
 $('#random').onclick=()=>openTip(Math.floor(Math.random()*100)+1);$('#detail-fav').onclick=()=>toggle('favorites',selected);$('#detail-done').onclick=()=>toggle('done',selected);$('#note').oninput=e=>{state.notes[selected]=e.target.value;if(!e.target.value.trim())delete state.notes[selected];persist();render()};$('#prev').onclick=()=>openTip(selected-1);$('#next').onclick=()=>openTip(selected+1);$('#close').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>document.body.style.overflow='');$('#detail').onclick=e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}};
 $('#export').onclick=()=>{const data={app:'100 Consejos Empresariales · Beacon',exportado:new Date().toISOString(),favoritos:state.favorites.map(id=>({id,titulo:tips[id-1].title})),completados:state.done.map(id=>({id,titulo:tips[id-1].title})),notas:state.notes};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='mis-consejos-beacon.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Tu espacio se ha exportado.')};
 document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();$('#search').focus()}});updateStats();render();if(!storageAvailable)toast('Usa Exportar mi espacio para conservar tus cambios.');
 if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
}
init();
